import fs from 'node:fs';

const file = 'random-dice-game-33.html';
let src = fs.readFileSync(file, 'utf8');
function replaceOnce(oldText, newText, label){
  const at = src.indexOf(oldText);
  if(at<0) throw new Error('Anchor not found: '+label);
  if(src.indexOf(oldText, at+oldText.length)>=0) throw new Error('Anchor not unique: '+label);
  src = src.slice(0,at)+newText+src.slice(at+oldText.length);
}
function insertBefore(anchor, text, label){ replaceOnce(anchor, text+'\n'+anchor, label); }

